def check(call, view, history):
    # Prevent exceeding the step budget by stopping tool calls early.
    # When 15 calls have already been executed, ask the model to produce the final answer instead.
    if view.get('calls_executed', 0) >= 15:
        return "Step budget is near limit – stop tool calls and finish the response now."
    return None

def check(call, view, history):
    limit = 15  # maximum allowed tool calls per request
    if view.get('calls_executed', 0) >= limit:
        return "Step budget reached – stop making tool calls and provide the final answer."
    return None
